import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 15
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter="\t",
        quotechar='"',
        doublequote=True,
    ))

    first_nonblank = None
    first_full_width = None
    header_index = None

    for index, record in enumerate(records):
        if not any(value.strip() for value in record):
            continue
        if first_nonblank is None:
            first_nonblank = index
        if len(record) == expected_width and first_full_width is None:
            first_full_width = index

        bilingual_pairs = sum(
            record[pos].strip().upper().startswith("EN_")
            and record[pos + 1].strip().upper().startswith("FR_")
            for pos in range(0, min(len(record), expected_width) - 1, 2)
        )
        if bilingual_pairs >= 3:
            header_index = index
            break

    if header_index is None:
        header_index = first_full_width
    if header_index is None:
        header_index = first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"column_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
